import {dataQuestionShow} from './data-question-view.js';
import {dataGuide} from './data-model.js';
import {dataLessons,distinctions,dataReferences,dataLearningSafeguards,dataLearningRelevance} from './data-learning.js';
export const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml;
const btn=(action,label,value='',style='primary')=>`<button class="dq-${style}" data-dq="${action}" data-value="${e(value)}" aria-pressed="${style==='pill-selected'}">${label}</button>`;
export const dataShow=dataQuestionShow;
export function dataLearn(s){const l=dataLessons[s.lesson],d=distinctions[s.distinction];return `<div class="dq-learn"><nav aria-label="Data learning modules">${dataLessons.map((x,i)=>`<button data-dq="lesson" data-value="${i}" class="${s.lesson===i?'selected':''}" aria-pressed="${s.lesson===i}">${x.name}</button>`).join('')}</nav><article><div class="eyebrow">LEARN / GUIDE THE DATA CONVERSATION</div><h1>${l.name}</h1><div class="dq-lesson-grid">${[['WHAT IT IS',l.what],['WHY IT EXISTS',l.why],['BUSINESS PROBLEM / EXAMPLE',l.example],['WHEN IT IS RELEVANT',dataLearningRelevance[l.name]],['WHAT SIGNAL TO LISTEN FOR',l.need],['WHAT NOT TO CLAIM',dataLearningSafeguards[l.name]||l.answer],['HOW IT CONNECTS',l.connect],['COMMON CUSTOMER QUESTION',`<strong>${l.question}</strong><br>${l.answer}`]].map(([title,text])=>`<section><h3>${title}</h3><p>${text}</p></section>`).join('')}</div><div class="dq-distinctions"><h2>Know the distinction.</h2><div class="dq-distinction-picker">${distinctions.map((x,i)=>btn('distinction',x[0],String(i),s.distinction===i?'pill-selected':'pill')).join('')}</div><div class="dq-distinction-body" aria-live="polite"><h3>${d[0]}</h3><div><p>${d[1]}</p><p>${d[2]}</p></div><strong>${d[3]}</strong></div></div><div class="dq-reference-links">${dataReferences.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('')}</div></article></div>`;}
export function dataSales(s){const g=dataGuide(s);return [['ASK',g.ask],['LISTEN FOR',g.listen],['PROBE',g.probe],['WHY IT MATTERS',g.cue],['NEXT MOVE',g.next]].map(([label,text])=>`<h3>${label}</h3><p>${text}</p>`).join('');}
